class Solution {
public:
    vector<int> getBiggestThree(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> dr(m, vector<int>(n, 0)), dl(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j) {
                dr[i][j] = grid[i][j] + (i > 0 && j > 0 ? dr[i-1][j-1] : 0);
                dl[i][j] = grid[i][j] + (i > 0 && j + 1 < n ? dl[i-1][j+1] : 0);
            }
        auto DR = [&](int r, int c) { return (r >= 0 && c >= 0) ? dr[r][c] : 0; };
        auto DL = [&](int r, int c) { return (r >= 0 && c < n) ? dl[r][c] : 0; };
        set<int> s;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j) {
                s.insert(grid[i][j]);
                if (s.size() > 3) s.erase(s.begin());
                int maxK = min(min(i, m - 1 - i), min(j, n - 1 - j));
                for (int k = 1; k <= maxK; ++k) {
                    long long sum =
                        (long long)(dl[i][j-k] - DL(i-k-1, j+1))
                      + (dr[i][j+k] - DR(i-k-1, j-1))
                      + (dr[i+k][j] - DR(i-1, j-k-1))
                      + (dl[i+k][j] - DL(i-1, j+k+1))
                      - grid[i-k][j] - grid[i+k][j]
                      - grid[i][j-k] - grid[i][j+k];
                    s.insert((int)sum);
                    if (s.size() > 3) s.erase(s.begin());
                }
            }
        return vector<int>(s.rbegin(), s.rend());
    }
};
